elif 'transfer_project' in request.POST:
    if not is_owner: return HttpResponseForbidden()
    membership = project.member_set.filter(user__email=email).get()
    project.member_set.update(transfer_request_date=None)  # revoke previous
    membership.transfer_request_date = now(); membership.save()
    profile.send_transfer_request(project)  # email

elif 'accept_transfer' in request.POST:
    tr = project.transfer_request()
    if not tr or tr.user != request.user: return HttpResponseForbidden()
    if not tr.can_accept(): return HttpResponseBadRequest()
    with transaction.atomic():
        tr.user = project.owner; tr.transfer_request_date = None; tr.role = Member.Role.REGULAR; tr.save()
        project.owner = request.user; project.save()

