@authorize
def create_check(request):
    spec = Spec.model_validate(request.json, strict=True)
    check = _lookup(request.project, spec)   # dedup by unique list
    if check is None:
        if request.project.num_checks_available() <= 0: return HttpResponseForbidden()
        check = Check(project=request.project); created = True
    _update(check, spec, request.v)
    if new_channels is not None: check.channel_set.set(new_channels)
    return JsonResponse(check.to_dict(v=request.v), status=201 if created else 200)

