@authorize
def pings(request, code):
    check = get_object_or_404(Check, code=code)
    if check.project_id != request.project.id: return HttpResponseForbidden()
    limit = min(profile.ping_log_limit, 1000)
    q = Ping.objects.filter(owner=check).order_by('-id').defer('body_raw')
    return JsonResponse({'pings': [p.to_dict(...) for p in list(q[:limit])]})

@cors('GET')
def ping_body(request, code, n):
    check = get_object_or_404(Check, code=code)
    if check.project_id != request.project.id: return HttpResponseForbidden()
    if n <= (check.n_pings - profile.ping_log_limit): raise Http404()
    ping = get_object_or_404(Ping, owner=check, n=n)
    return HttpResponse(ping.get_body_bytes(), content_type='text/plain')

def flips(request, check):
    if check.project_id != request.project.id: return HttpResponseForbidden()
    flips = Flip.objects.filter(owner=check).order_by('-id')
    if form.cleaned_data['start']: flips = flips.filter(created__gte=form.cleaned_data['start'])
    if form.cleaned_data['end']: flips = flips.filter(created__lt=form.cleaned_data['end'])
    return JsonResponse({'flips': [flip.to_dict() for flip in flips]})

